+// ResetPassword removes every session belonging to userID, forcing that user
+// to sign in again. It returns ErrNotFound when the user has no sessions.
+func (s *Store) ResetPassword(userID string) error {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	removed := 0
+	for id, session := range s.sessions {
+		if session.User == userID {
+			delete(s.sessions, id)
+			removed++
+		}
+	}
+	if removed == 0 {
+		return ErrNotFound
+	}
+	return nil
+}
