+func TestDeleteAllForUserIdempotent(t *testing.T) {
+	store := NewStore(time.Minute)
+
+	// A user with no sessions must yield 0, not an error.
+	if got := store.DeleteAllForUser("nobody"); got != 0 {
+		t.Fatalf("DeleteAllForUser on empty store = %d, want 0", got)
+	}
+
+	store.Create("a1", "ada")
+	store.Create("a2", "ada")
+	store.Create("g1", "grace")
+	if store.Len() != 3 {
+		t.Fatalf("store length after create = %d, want 3", store.Len())
+	}
+
+	if got := store.DeleteAllForUser("ada"); got != 2 {
+		t.Fatalf("DeleteAllForUser(ada) = %d, want 2", got)
+	}
+	if store.Len() != 1 {
+		t.Fatalf("store length after delete-all = %d, want 1", store.Len())
+	}
+	if _, err := store.Get("g1"); err != nil {
+		t.Fatalf("other user's session was removed: %v", err)
+	}
+	for _, id := range []string{"a1", "a2"} {
+		if _, err := store.Get(id); !errors.Is(err, ErrNotFound) {
+			t.Fatalf("Get(%q) after delete-all = %v, want ErrNotFound", id, err)
+		}
+	}
+
+	// Running it again is a silent no-op: 0 removed, still no error.
+	if got := store.DeleteAllForUser("ada"); got != 0 {
+		t.Fatalf("second DeleteAllForUser(ada) = %d, want 0", got)
+	}
+	if store.Len() != 1 {
+		t.Fatalf("store length after second delete-all = %d, want 1", store.Len())
+	}
+
+	// A fresh session for the same user can still be created and retrieved.
+	store.Create("a3", "ada")
+	if _, err := store.Get("a3"); err != nil {
+		t.Fatalf("Get after re-create: %v", err)
+	}
+	if got := store.DeleteAllForUser("ada"); got != 1 {
+		t.Fatalf("DeleteAllForUser(ada) after re-create = %d, want 1", got)
+	}
+}
