+// SessionsForUser returns the live sessions belonging to user, ordered by
+// session id so callers see a stable result. Expired sessions are not
+// reported; this method does not drop them from the map.
+//
+// Locking: takes the read lock (s.mu.RLock) because it only reads the
+// s.sessions map; it performs no mutation, so it must not delete, refresh, or
+// otherwise rewrite entries even for expired sessions. Concurrent readers may
+// proceed in parallel while writers are excluded.
+func (s *Store) SessionsForUser(user string) []Session {
+	s.mu.RLock()
+	defer s.mu.RUnlock()
+	now := s.now()
+	out := make([]Session, 0)
+	for _, session := range s.sessions {
+		if session.User != user {
+			continue
+		}
+		if now.Sub(session.LastSeen) > s.ttl {
+			continue
+		}
+		out = append(out, session)
+	}
+	sort.Slice(out, func(i, j int) bool {
+		return out[i].ID < out[j].ID
+	})
+	return out
+}
