+package main
+
+import (
+	"errors"
+	"testing"
+	"time"
+)
+
+// TestSessionExpiryTable is the single table-driven home for session expiry
+// behaviour. All cases share one controllable store.now clock.
+func TestSessionExpiryTable(t *testing.T) {
+	const ttl = time.Minute
+	base := time.Date(2024, time.January, 1, 12, 0, 0, 0, time.UTC)
+
+	tests := []struct {
+		name       string
+		advance    time.Duration
+		wantErr    error
+		wantFound  bool
+		wantLen    int
+	}{
+		{
+			name:      "fresh session is readable",
+			advance:   0,
+			wantFound: true,
+			wantLen:   1,
+		},
+		{
+			name:      "session exactly at ttl is still live",
+			advance:   ttl,
+			wantFound: true,
+			wantLen:   1,
+		},
+		{
+			name:      "session one second past ttl is expired",
+			advance:   ttl + time.Second,
+			wantErr:   ErrNotFound,
+			wantFound: false,
+			wantLen:   0,
+		},
+		{
+			name:      "session well past ttl is dropped from the store",
+			advance:   2 * time.Minute,
+			wantErr:   ErrNotFound,
+			wantFound: false,
+			wantLen:   0,
+		},
+	}
+
+	for _, tc := range tests {
+		t.Run(tc.name, func(t *testing.T) {
+			store := NewStore(ttl)
+			clock := base
+			store.now = func() time.Time { return clock }
+
+			store.Create("abc", "ada")
+			if store.Len() != 1 {
+				t.Fatalf("after Create: store length = %d, want 1", store.Len())
+			}
+
+			clock = clock.Add(tc.advance)
+			got, err := store.Get("abc")
+
+			if !errors.Is(err, tc.wantErr) {
+				t.Fatalf("Get error = %v, want %v", err, tc.wantErr)
+			}
+			if tc.wantFound {
+				if err != nil {
+					t.Fatalf("Get: %v", err)
+				}
+				if got.ID != "abc" || got.User != "ada" {
+					t.Fatalf("found session = %+v, want abc/ada", got)
+				}
+			} else if got != (Session{}) {
+				t.Fatalf("expired Get returned %+v, want zero Session", got)
+			}
+
+			if store.Len() != tc.wantLen {
+				t.Fatalf("store length = %d, want %d", store.Len(), tc.wantLen)
+			}
+		})
+	}
+}

