+package main
+
+import (
+	"errors"
+	"testing"
+	"time"
+)
+
+// TestSessionExpiryTable covers every session expiry boundary against a
+// controllable store.now clock. All cases live in this one table.
+func TestSessionExpiryTable(t *testing.T) {
+	const ttl = time.Minute
+
+	cases := []struct {
+		name        string
+		advance     time.Duration
+		wantErr     error
+		wantLen     int
+		wantRefresh bool
+	}{
+		{
+			name:    "fresh session is readable",
+			advance: 0,
+			wantErr: nil,
+			wantLen: 1,
+		},
+		{
+			name:    "exactly ttl is still live",
+			advance: ttl,
+			wantErr: nil,
+			wantLen: 1,
+		},
+		{
+			name:    "one second past ttl is expired",
+			advance: ttl + time.Second,
+			wantErr: ErrNotFound,
+			wantLen: 0,
+		},
+		{
+			name:    "expired session is dropped",
+			advance: ttl + time.Second,
+			wantErr: ErrNotFound,
+			wantLen: 0,
+		},
+	}
+
+	for _, tc := range cases {
+		t.Run(tc.name, func(t *testing.T) {
+			store := NewStore(ttl)
+			clock := time.Unix(1_700_000_000, 0)
+			store.now = func() time.Time { return clock }
+
+			created := store.Create("abc", "ada")
+
+			clock = clock.Add(tc.advance)
+			got, err := store.Get("abc")
+
+			if tc.wantErr != nil {
+				if !errors.Is(err, tc.wantErr) {
+					t.Fatalf("Get after %v = %v, want %v", tc.advance, err, tc.wantErr)
+				}
+			} else {
+				if err != nil {
+					t.Fatalf("Get after %v: %v", tc.advance, err)
+				}
+				if got.ID != "abc" || got.User != "ada" {
+					t.Fatalf("got session = %+v, want abc/ada", got)
+				}
+				if !got.Created.Equal(created.Created) {
+					t.Fatalf("created = %v, want %v", got.Created, created.Created)
+				}
+				if !got.LastSeen.Equal(clock) {
+					t.Fatalf("last seen = %v, want refreshed to %v", got.LastSeen, clock)
+				}
+			}
+
+			if store.Len() != tc.wantLen {
+				t.Fatalf("store length after %v = %d, want %d", tc.advance, store.Len(), tc.wantLen)
+			}
+		})
+	}
+}

