+package main
+
+import (
+	"runtime"
+	"testing"
+)
+
+// platformNote is implemented twice, once under //go:build unix
+// (session_unix.go -> "unix") and once under //go:build !unix
+// (session_other.go -> "other"). Each test binary therefore compiles
+// exactly one variant, and this test pins the value that variant
+// must return for the running GOOS.
+
+func TestPlatformNoteMatchesUnixBuildTag(t *testing.T) {
+	got := platformNote()
+
+	if isUnixGOOS(runtime.GOOS) {
+		if got != "unix" {
+			t.Fatalf("platformNote() under a unix GOOS (%s) = %q, want %q", runtime.GOOS, got, "unix")
+		}
+		return
+	}
+
+	if got != "other" {
+		t.Fatalf("platformNote() under non-unix GOOS (%s) = %q, want %q", runtime.GOOS, got, "other")
+	}
+}
+
+func TestPlatformNoteIsNeverEmpty(t *testing.T) {
+	if got := platformNote(); got == "" {
+		t.Fatal("platformNote() returned an empty string; both build-tagged variants must return a non-empty marker")
+	}
+}
+
+func TestPlatformNoteIsOneOfTheTwoVariants(t *testing.T) {
+	got := platformNote()
+	if got != "unix" && got != "other" {
+		t.Fatalf("platformNote() = %q, want one of %q, %q", got, "unix", "other")
+	}
+}
+
+// isUnixGOOS mirrors the GOOS set that the `unix` build constraint matches,
+// so the expectation above tracks the same decision the compiler made when
+// selecting session_unix.go vs session_other.go.
+func isUnixGOOS(goos string) bool {
+	switch goos {
+	case "aix", "android", "darwin", "dragonfly", "freebsd", "hurd", "illumos", "ios", "linux", "netbsd", "openbsd", "solaris":
+		return true
+	default:
+		return false
+	}
+}
