+	defer s.mu.RUnlock()
+	sessions := make([]Session, 0, len(s.sessions))
+	for _, session := range s.sessions {
+		if s.now().Sub(session.LastSeen) > s.ttl {
+			continue
+		}
+		sessions = append(sessions, session)
+	}
+	return sessions, nil
