+package main
+
+import (
+	"errors"
+	"testing"
+	"time"
+)
+
+// TestSessionExpiryTable consolidates the expiry behaviour of Store in one
+// table. Every case drives the store through a controllable now clock.
+func TestSessionExpiryTable(t *testing.T) {
+	const (
+		ttl   = time.Minute
+		shift = time.Second
+	)
+
+	cases := []struct {
+		name        string
+		advance     time.Duration
+		wantErr     error
+		wantID      string
+		wantLen     int
+		refreshedAt bool
+	}{
+		{
+			name:    "fresh session is readable",
+			advance: 0,
+			wantErr: nil,
+			wantID:  "abc",
+			wantLen: 1,
+		},
+		{
+			name:    "exactly ttl is still live",
+			advance: ttl,
+			wantErr: nil,
+			wantID:  "abc",
+			wantLen: 1,
+		},
+		{
+			name:    "one second past ttl is expired",
+			advance: ttl + shift,
+			wantErr: ErrNotFound,
+			wantLen: 0,
+		},
+		{
+			name:    "expired session is dropped from the store",
+			advance: 2 * ttl,
+			wantErr: ErrNotFound,
+			wantLen: 0,
+		},
+	}
+
+	for _, tc := range cases {
+		t.Run(tc.name, func(t *testing.T) {
+			store := NewStore(ttl)
+			clock := time.Date(2024, time.January, 1, 12, 0, 0, 0, time.UTC)
+			store.now = func() time.Time { return clock }
+
+			created := store.Create("abc", "ada")
+
+			clock = clock.Add(tc.advance)
+
+			session, err := store.Get("abc")
+			if !errors.Is(err, tc.wantErr) {
+				t.Fatalf("Get after %v: err = %v, want %v", tc.advance, err, tc.wantErr)
+			}
+			if tc.wantErr != nil {
+				if session != (Session{}) {
+					t.Fatalf("expired Get returned session %+v, want zero value", session)
+				}
+			} else {
+				if session.ID != tc.wantID || session.User != "ada" {
+					t.Fatalf("Get = %+v, want id %q user ada", session, tc.wantID)
+				}
+				if !session.LastSeen.Equal(clock) {
+					t.Fatalf("LastSeen = %v, want refreshed to %v", session.LastSeen, clock)
+				}
+				if !session.Created.Equal(created.Created) {
+					t.Fatalf("Created = %v, want %v", session.Created, created.Created)
+				}
+			}
+
+			if store.Len() != tc.wantLen {
+				t.Fatalf("store length = %d, want %d", store.Len(), tc.wantLen)
+			}
+		})
+	}
+}

