@@ -0,0 +1,91 @@
+package main
+
+import (
+	"errors"
+	"testing"
+	"time"
+)
+
+// TestSessionExpiryTable drives the store's idle-expiry behaviour from one
+// table. Every case shares the same controllable store.now clock so that
+// "now" is exactly known at each assertion point.
+func TestSessionExpiryTable(t *testing.T) {
+	const ttl = time.Minute
+
+	tests := []struct {
+		name        string
+		advance     time.Duration // time moved past Created before Get
+		wantErr     error         // nil means the session must still be readable
+		wantLen     int           // store length after Get
+		wantRefresh bool          // LastSeen must advance to the new now
+	}{
+		{
+			name:        "fresh session is readable",
+			advance:     10 * time.Second,
+			wantErr:     nil,
+			wantLen:     1,
+			wantRefresh: true,
+		},
+		{
+			name:        "exactly ttl is still live",
+			advance:     ttl,
+			wantErr:     nil,
+			wantLen:     1,
+			wantRefresh: true,
+		},
+		{
+			name:        "one second past ttl is expired",
+			advance:     ttl + time.Second,
+			wantErr:     ErrNotFound,
+			wantLen:     0,
+			wantRefresh: false,
+		},
+		{
+			name:        "expired session is dropped",
+			advance:     10 * ttl,
+			wantErr:     ErrNotFound,
+			wantLen:     0,
+			wantRefresh: false,
+		},
+	}
+
+	for _, tc := range tests {
+		t.Run(tc.name, func(t *testing.T) {
+			start := time.Date(2024, time.January, 1, 12, 0, 0, 0, time.UTC)
+			clock := start
+			store := NewStore(ttl)
+			store.now = func() time.Time { return clock }
+
+			created := store.Create("abc", "ada")
+			if created.Created != start || created.LastSeen != start {
+				t.Fatalf("created at %v, want %v", created.Created, start)
+			}
+
+			clock = start.Add(tc.advance)
+			got, err := store.Get("abc")
+
+			if !errors.Is(err, tc.wantErr) {
+				t.Fatalf("Get after %v = %v, want %v", tc.advance, err, tc.wantErr)
+			}
+			if tc.wantErr != nil {
+				if got != (Session{}) {
+					t.Fatalf("expired Get returned %+v, want zero Session", got)
+				}
+			} else {
+				if got.ID != "abc" || got.User != "ada" {
+					t.Fatalf("session = %+v, want abc/ada", got)
+				}
+				if got.Created != start {
+					t.Fatalf("Created = %v, want %v", got.Created, start)
+				}
+				if tc.wantRefresh && got.LastSeen != clock {
+					t.Fatalf("LastSeen = %v, want refreshed %v", got.LastSeen, clock)
+				}
+			}
+
+			if store.Len() != tc.wantLen {
+				t.Fatalf("store length = %d, want %d", store.Len(), tc.wantLen)
+			}
+		})
+	}
+}

